INSERT INTO _fleet_sync_databases(database,lifecycle_kind,origin_kind,origin_epoch,origin_sequence,import_digest,retiring_attempt,retired_at,revision_epoch,revision_change,changed_at,created_at,updated_at) VALUES(?1,json_extract(?2,'$.lifecycle.state'),json_extract(?2,'$.lifecycle.origin.kind'),NULLIF(?2 -> '$.lifecycle.origin.value.position.epoch','null'),NULLIF(?2 -> '$.lifecycle.origin.value.position.sequence','null'),coalesce(json_extract(?2,'$.lifecycle.importedFrom.digest'),json_extract(?2,'$.lifecycle.importDigest')),json_extract(?2,'$.lifecycle.attempt'),json_extract(?2,'$.lifecycle.at'),NULLIF(?2 -> '$.revision.epoch','null'),NULLIF(?2 -> '$.revision.change','null'),json_extract(?2,'$.changed_at'),CAST(?3 AS INTEGER),CAST(?4 AS INTEGER)) ON CONFLICT(database) DO UPDATE SET lifecycle_kind=excluded.lifecycle_kind,origin_kind=excluded.origin_kind,origin_epoch=excluded.origin_epoch,origin_sequence=excluded.origin_sequence,import_digest=excluded.import_digest,retiring_attempt=excluded.retiring_attempt,retired_at=excluded.retired_at,revision_epoch=excluded.revision_epoch,revision_change=excluded.revision_change,changed_at=excluded.changed_at,updated_at=excluded.updated_at
